using Microsoft.EntityFrameworkCore;

public static class OrderExport
{
    public static async Task WriteAsync(
        ShopDb db, TextWriter csv, CancellationToken ct)
    {
        // Async, yet every order is loaded and tracked before line one
        var orders = await db.Orders.ToListAsync(ct);
        foreach (var o in orders)
            await csv.WriteLineAsync($"{o.Id},{o.CustomerId},{o.Total}");
    }
}

using Microsoft.EntityFrameworkCore;

public static class OrderExport
{
    public static async Task WriteAsync(
        ShopDb db, TextWriter csv, CancellationToken ct)
    {
        // A projection isn't tracked; AsAsyncEnumerable reads row by row
        var rows = db.Orders
            .Select(o => new { o.Id, o.CustomerId, o.Total })
            .AsAsyncEnumerable();
        await foreach (var o in rows.WithCancellation(ct))
            await csv.WriteLineAsync($"{o.Id},{o.CustomerId},{o.Total}");
    }
}

