using Microsoft.EntityFrameworkCore;

public static class TierRecalculation
{
    public static async Task RunAsync(ShopDb db, CancellationToken ct)
    {
        var lastId = 0;
        while (true)
        {
            // Keyset batch: WHERE Id > lastId, no OFFSET, at most 1,000 rows
            var batch = await db.Customers.Where(c => c.Id > lastId)
                .OrderBy(c => c.Id).Take(1_000).ToListAsync(ct);
            if (batch.Count == 0) break;
            foreach (var c in batch) c.RecalculateTier();
            await db.SaveChangesAsync(ct);
            db.ChangeTracker.Clear(); // release this batch
            lastId = batch[^1].Id;
        }
    }
}
